'use strict';
const $=id=>document.getElementById(id);
function parseBarcode(raw){const v=(raw||'').toUpperCase().replace(/[\s*]/g,'');const m=/^(P\d{5,7}[A-Z]{1,3})(\d*)$/.exec(v);if(!m)return null;const suffix=m[2];if(!suffix)return {code:m[1],page:null,total:null};if(suffix.length<3)return null;const page=Number.parseInt(suffix.slice(0,-2),10),total=Number.parseInt(suffix.slice(-2),10);return page>0&&page<=total?{code:m[1],page,total}:null}
function node(tag,text,cls){const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e}
function resource(url,title,subtitle,cls){const a=node('a',null,'doc-link '+(cls||''));a.href=url;const t=node('span',title);t.append(node('small',subtitle));a.append(t,node('span','↗'));return a}
async function render(){const out=$('resultDetail'),barcode=parseBarcode(new URLSearchParams(location.search).get('barcode'));if(!barcode){out.replaceChildren(node('div','INVALID BARCODE','eyebrow'),node('h1','无法识别这个条码'),node('p','返回后重新扫描完整的 P 开头条码。'));return}try{const data=await fetch('papers.json').then(r=>{if(!r.ok)throw Error();return r.json()}),paper=data.papers.find(x=>x.code===barcode.code);if(!paper){out.replaceChildren(node('div','NOT FOUND','eyebrow'),node('h1','暂未收录这份试卷'),node('p',barcode.code,'paper-code'),node('p','返回后可以重试，或前往 PaperLords / Pearson 目录查询。'));return}out.replaceChildren(node('div',`${paper.qualification} · ${paper.subject}`,'eyebrow'),node('span',paper.session,'pill'),node('h1',paper.name),node('p',`${paper.unit} · ${barcode.code}`,'paper-code'));if(barcode.page)out.append(node('p',`第 ${barcode.page} / ${barcode.total} 页`,'page-tracker'));const choices=node('div',null,'choices'),pageUrl=barcode.page?`${paper.qp}#page=${barcode.page}`:paper.qp;choices.append(resource(pageUrl,barcode.page?`打开第 ${barcode.page} 页`:'打开试卷',barcode.page?'对应扫描页':'Question paper','page-choice'),resource(paper.qp,'打开全卷','从第 1 页开始','full-choice'));if(paper.ms)choices.append(resource(paper.ms,'打开 MS','Mark scheme','ms'));out.append(choices,node('p',`资料链接来自 ${paper.source||'公开试卷目录'}；使用浏览器返回即可回到本页。`,'download-note'))}catch{out.replaceChildren(node('div','LOAD ERROR','eyebrow'),node('h1','结果载入失败'),node('p','请检查网络后返回重试。'))}}
render();
